#include <bits/stdc++.h>
using namespace std;

struct Point {
    int v, w, x, y, z;
    Point(int a, int b, int c, int d, int e) : v(a), w(b), x(c), y(d), z(e) {}
    double getMagnitude() const {
        return sqrt((double)(v * v + w * w + x * x + y * y + z * z));
    }
};

bool isAngleLessThan90Degrees(const Point& p1, const Point& p2) {
    double mag1 = p1.getMagnitude();
    double mag2 = p2.getMagnitude();
    double dot = p1.v * p2.v + p1.w * p2.w + p1.x * p2.x + p1.y * p2.y + p1.z * p2.z;
    double angle = acos(dot / (mag1 * mag2)) * 180.0 / M_PI;
    return angle < 90.0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 11) {
        cout << 0 << "\n";
        return 0;
    }
    vector<Point> points;
    for (int i = 0; i < n; i++) {
        int a, b, c, d, e;
        cin >> a >> b >> c >> d >> e;
        points.emplace_back(a, b, c, d, e);
    }
    unordered_set<int> validIndices;
    for (int i = 0; i < n; i++) {
        bool isValid = true;
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                if (i != j && i != k && j != k) {
                    Point p1 = points[j];
                    Point p2 = points[k];
                    Point p3 = points[i];
                    Point v1(p1.v - p3.v, p1.w - p3.w, p1.x - p3.x, p1.y - p3.y, p1.z - p3.z);
                    Point v2(p2.v - p3.v, p2.w - p3.w, p2.x - p3.x, p2.y - p3.y, p2.z - p3.z);
                    if (isAngleLessThan90Degrees(v1, v2)) {
                        isValid = false;
                    }
                }
            }
        }
        if (isValid) {
            validIndices.insert(i + 1);
        }
    }
    if (validIndices.empty()) {
        cout << 0 << "\n";
    } else {
        cout << validIndices.size() << "\n";
        for (int idx : validIndices) {
            cout << idx << "\n";
        }
    }
    return 0;
}

